"  const [tableCustomers, setTableCustomers] = useState(() => {
    try {
      const saved = localStorage.getItem('pos_table_customers');
      return saved ? JSON.parse(saved) : {};
    } catch (e) { return {}; }
  });

  useEffect(() => {
    if (selectedTable && !isRestoringCustomerRef.current) {
      setTableCustomers(prev => ({
        ...prev,
        [selectedTable.id]: {
          customerCountryCode,
          customerPhone,
          customerName,
          customerAddress,
          selectedCustomer,
          redeemedPoints,
          appliedCoupon,
          couponCode
        }
      }));
    }
  }, [
    selectedTable,
    customerCountryCode,
    customerPhone,
    customerName,
    customerAddress,
    selectedCustomer,
    redeemedPoints,
    appliedCoupon,
    couponCode
  ]);

  useEffect(() => {
    localStorage.setItem('pos_table_customers', JSON.stringify(tableCustomers));
  }, [tableCustomers]);"
